const lessons=[{"sentences":[{"speaker":"A","text":"Excuse me because I cannot find this blue sweater in a medium size on the display rack.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.623541666666667},{"speaker":"B","text":"Let me check our storage inventory on this computer system right now to see if we have more.","position":2,"audioStartSeconds":5.823541666666666,"audioEndSeconds":11.434208333333334},{"speaker":"A","text":"Thank you because my sister really wants that specific color for her birthday next week.","position":3,"audioStartSeconds":11.634208333333333,"audioEndSeconds":17.008708333333335},{"speaker":"B","text":"We actually have two medium sweaters arriving with our morning delivery truck tomorrow.","position":4,"audioStartSeconds":17.208708333333334,"audioEndSeconds":22.621875},{"speaker":"A","text":"That is wonderful news so can you put one aside for me to purchase tomorrow afternoon?","position":5,"audioStartSeconds":22.821875,"audioEndSeconds":27.886291666666665},{"speaker":"B","text":"I will hold it at the customer service desk under your name if you provide it.","position":6,"audioStartSeconds":28.086291666666668,"audioEndSeconds":32.88008333333333},{"speaker":"A","text":"Hello I am calling to confirm when my ordered office furniture will be ready for store collection.","role":"section-start","position":7,"audioStartSeconds":37.88008333333333,"audioEndSeconds":43.56308333333333},{"speaker":"B","text":"Good afternoon and please give me your receipt number so I can look up your order.","position":8,"audioStartSeconds":43.763083333333334,"audioEndSeconds":48.47958333333333},{"speaker":"A","text":"My receipt number is four five nine two and I paid for the desk last Friday.","position":9,"audioStartSeconds":48.67958333333333,"audioEndSeconds":53.898666666666664},{"speaker":"B","text":"Your large wooden desk arrived this morning and our staff finished assembling it a moment ago.","position":10,"audioStartSeconds":54.09866666666667,"audioEndSeconds":59.48525},{"speaker":"A","text":"Can I pick it up this evening after I finish working at my office?","position":11,"audioStartSeconds":59.68525,"audioEndSeconds":63.849291666666666},{"speaker":"B","text":"We are open until eight o clock tonight so you can collect it anytime before closing.","position":12,"audioStartSeconds":64.04929166666666,"audioEndSeconds":69.13270833333333}],"questions":[{"prompt":"What item is the customer looking for?","options":["A red jacket.","A blue sweater.","A green shirt."],"answer":"B","evidenceSentence":1,"evidence":"cannot find this blue sweater","explanation":"Người mua hàng đang tìm một chiếc áo len màu xanh dương."},{"prompt":"When will new stock arrive at the store?","options":["Tomorrow morning.","Next week.","This evening."],"answer":"A","evidenceSentence":4,"evidence":"arriving with our morning delivery truck tomorrow","explanation":"Hàng mới sẽ đến vào buổi sáng ngày mai."},{"prompt":"Where will the item be kept for the customer?","options":["In the storage room.","At the customer service desk.","On the display rack."],"answer":"B","evidenceSentence":6,"evidence":"hold it at the customer service desk","explanation":"Nhân viên sẽ giữ món đồ ở quầy dịch vụ khách hàng."},{"prompt":"Why is the second caller phoning the store?","options":["To buy a new desk.","To check a collection date.","To return an item."],"answer":"B","evidenceSentence":7,"evidence":"confirm when my ordered office furniture will be ready","explanation":"Người gọi thứ hai muốn xác nhận thời gian nhận đồ đặt trước."},{"prompt":"What has the staff recently done with the desk?","options":["Delivered it to an office.","Finished assembling it.","Placed it on sale."],"answer":"B","evidenceSentence":10,"evidence":"staff finished assembling it a moment ago","explanation":"Nhân viên cửa hàng vừa mới lắp ráp xong chiếc bàn."},{"prompt":"Until what time is the store open tonight?","options":["Six o clock.","Seven o clock.","Eight o clock."],"answer":"C","evidenceSentence":12,"evidence":"We are open until eight o clock tonight","explanation":"Cửa hàng mở cửa đến 8 giờ tối nay."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
